'use strict';

/**
* LAPACK routine to generate a real elementary reflector (Householder matrix).
*
* @module @stdlib/lapack/base/dlarfg
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlarfg = require( '@stdlib/lapack/base/dlarfg' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
*
* var tau = dlarfg( 3, 4.0, x, 1 );
* // tau => ~1.714...
*
* // x now contains v[1:N]
* // x => <Float64Array>[ ~-0.557..., ~-0.742..., ~-0.371... ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlarfg = require( '@stdlib/lapack/base/dlarfg' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
*
* var tau = dlarfg.ndarray( 3, 4.0, x, 1, 0 );
* // tau => ~1.714...
*
* // x now contains v[1:N]
* // x => <Float64Array>[ ~-0.557..., ~-0.742..., ~-0.371... ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
